#include "AudioticonCore.h"

// Generated by cxx-build and published to backend/target/cxxbridge by
// backend/crates/bridge/build.rs. rustlink.pri puts that directory on the
// include path. cxx inlines the Rust support types (rust::Str, rust::String,
// rust::Box) into this header, so there is nothing else to include.
#include "audioticon-bridge/src/lib.rs.h"

#include <QDebug>

#include <cstdint>
#include <exception>
#include <optional>
#include <string>

namespace audioticon::ui {

namespace {

JobStage mapStage(::audioticon::bridge::TaskStage stage)
{
    using Rust = ::audioticon::bridge::TaskStage;
    switch (stage) {
    case Rust::Idle:
        return JobStage::Idle;
    case Rust::Queued:
        return JobStage::Queued;
    case Rust::Normalizing:
        return JobStage::Normalizing;
    case Rust::Synthesizing:
        return JobStage::Synthesizing;
    case Rust::Mastering:
        return JobStage::Mastering;
    case Rust::Finished:
        return JobStage::Finished;
    case Rust::Failed:
        return JobStage::Failed;
    case Rust::Cancelled:
        return JobStage::Cancelled;
    }
    return JobStage::Idle;
}

QString toQString(const ::rust::String &value)
{
    return QString::fromUtf8(value.data(), static_cast<int>(value.size()));
}

ModelInfo toModelInfo(const ::audioticon::bridge::ModelInfoDto &dto)
{
    ModelInfo info;
    info.id = toQString(dto.id);
    info.kind = toQString(dto.kind);
    info.name = toQString(dto.name);
    info.path = toQString(dto.path);
    info.format = toQString(dto.format);
    info.language = toQString(dto.language);
    info.sizeBytes = static_cast<qint64>(dto.size_bytes);
    info.license = toQString(dto.license);
    info.status = toQString(dto.status);
    info.checksumSha256 = toQString(dto.checksum_sha256);
    info.detail = toQString(dto.detail);
    return info;
}

} // namespace

int coreSampleRate()
{
    // A panic across the FFI boundary aborts rather than unwinding into Qt;
    // core_version() only reads a constant, so there is nothing to catch here.
    return static_cast<int>(::audioticon::bridge::core_version());
}

QString jobStageName(JobStage stage)
{
    switch (stage) {
    case JobStage::Idle:
        return QStringLiteral("Idle");
    case JobStage::Queued:
        return QStringLiteral("Queued");
    case JobStage::Normalizing:
        return QStringLiteral("Normalizing");
    case JobStage::Synthesizing:
        return QStringLiteral("Synthesizing");
    case JobStage::Mastering:
        return QStringLiteral("Mastering");
    case JobStage::Finished:
        return QStringLiteral("Finished");
    case JobStage::Failed:
        return QStringLiteral("Failed");
    case JobStage::Cancelled:
        return QStringLiteral("Cancelled");
    }
    return QStringLiteral("Idle");
}

struct CoreSession::Impl {
    // `rust::Box` has no default constructor, and a failed create_engine() must
    // not take the whole application down, so the engine is optional.
    std::optional<::rust::Box<::audioticon::bridge::BridgeEngine>> engine;
};

CoreSession::CoreSession()
    : m_impl(std::make_unique<Impl>())
{
    try {
        m_impl->engine.emplace(::audioticon::bridge::create_engine());
    } catch (const std::exception &error) {
        qWarning("AudioticonCore: nie można utworzyć silnika Rust: %s", error.what());
    } catch (...) {
        qWarning("AudioticonCore: nie można utworzyć silnika Rust (nieznany błąd)");
    }
}

CoreSession::~CoreSession() = default;

quint64 CoreSession::startJob(const QString &text, const QString &outputDir, QString *errorOut)
{
    if (!m_impl->engine) {
        if (errorOut)
            *errorOut = QStringLiteral("Silnik Rust nie został zainicjalizowany");
        return 0;
    }

    try {
        // toStdString() is UTF-8, which is what rust::Str expects.
        const std::string utf8Text = text.toStdString();
        const std::string utf8Dir = outputDir.toStdString();
        const std::uint64_t jobId =
            ::audioticon::bridge::start_job(**m_impl->engine, utf8Text, utf8Dir);
        return static_cast<quint64>(jobId);
    } catch (const std::exception &error) {
        // cxx surfaces `Result<u64>` errors as a thrown exception whose what()
        // is the Rust error message.
        if (errorOut)
            *errorOut = QString::fromUtf8(error.what());
    } catch (...) {
        if (errorOut)
            *errorOut = QStringLiteral("Nieznany błąd rdzenia Rust");
    }
    return 0;
}

JobSnapshot CoreSession::jobState(quint64 jobId) const
{
    JobSnapshot snapshot;
    snapshot.jobId = jobId;
    if (!m_impl->engine)
        return snapshot;

    const auto state = ::audioticon::bridge::job_state(**m_impl->engine, jobId);
    snapshot.jobId = static_cast<quint64>(state.job_id);
    snapshot.stage = mapStage(state.stage);
    snapshot.percent = static_cast<double>(state.progress_percent);
    snapshot.currentSegment = static_cast<int>(state.current_segment);
    snapshot.totalSegments = static_cast<int>(state.total_segments);
    snapshot.statusMessage = toQString(state.status_message);
    snapshot.errorMessage = toQString(state.error_message);
    snapshot.outputPath = toQString(state.output_path);
    return snapshot;
}

bool CoreSession::cancelJob(quint64 jobId)
{
    if (!m_impl->engine)
        return false;
    return ::audioticon::bridge::cancel_job(**m_impl->engine, jobId);
}

QVector<ModelInfo> CoreSession::listModels() const
{
    QVector<ModelInfo> result;
    if (!m_impl->engine)
        return result;

    try {
        const auto models = ::audioticon::bridge::list_models(**m_impl->engine);
        result.reserve(static_cast<int>(models.size()));
        for (const auto &model : models)
            result.append(toModelInfo(model));
    } catch (const std::exception &error) {
        qWarning("AudioticonCore: list_models nie powiodło się: %s", error.what());
    }
    return result;
}

std::optional<ModelInfo> CoreSession::inspectModel(const QString &id) const
{
    if (!m_impl->engine)
        return std::nullopt;

    try {
        return toModelInfo(
            ::audioticon::bridge::inspect_model(**m_impl->engine, id.toStdString()));
    } catch (const std::exception &) {
        // cxx turns the Rust Result error into an exception; an unknown id is
        // exactly the "no such model" answer the caller expects.
        return std::nullopt;
    }
}

std::optional<ModelInfo> CoreSession::selectModel(const QString &id, QString *errorOut)
{
    if (!m_impl->engine) {
        if (errorOut)
            *errorOut = QStringLiteral("Silnik Rust nie został zainicjalizowany");
        return std::nullopt;
    }

    try {
        return toModelInfo(
            ::audioticon::bridge::select_model(**m_impl->engine, id.toStdString()));
    } catch (const std::exception &error) {
        if (errorOut)
            *errorOut = QString::fromUtf8(error.what());
    } catch (...) {
        if (errorOut)
            *errorOut = QStringLiteral("Nieznany błąd rdzenia Rust");
    }
    return std::nullopt;
}

ModelCatalogStatus CoreSession::modelStatus() const
{
    ModelCatalogStatus status;
    if (!m_impl->engine)
        return status;

    try {
        const auto dto = ::audioticon::bridge::model_status(**m_impl->engine);
        status.catalogRoot = toQString(dto.catalog_root);
        status.rootExists = dto.root_exists;
        status.total = static_cast<int>(dto.total);
        status.available = static_cast<int>(dto.available);
        status.unavailable = static_cast<int>(dto.unavailable);
        status.activeId = toQString(dto.active_id);
        status.activeKind = toQString(dto.active_kind);
        status.activePath = toQString(dto.active_path);
        status.activeStatus = toQString(dto.active_status);
        status.piperModelPath = toQString(dto.piper_model_path);
        status.message = toQString(dto.message);
    } catch (const std::exception &error) {
        qWarning("AudioticonCore: model_status nie powiodło się: %s", error.what());
    }
    return status;
}

bool CoreSession::clearModelSelection(QString *errorOut)
{
    if (!m_impl->engine) {
        if (errorOut)
            *errorOut = QStringLiteral("Silnik Rust nie został zainicjalizowany");
        return false;
    }

    try {
        ::audioticon::bridge::clear_model_selection(**m_impl->engine);
        return true;
    } catch (const std::exception &error) {
        if (errorOut)
            *errorOut = QString::fromUtf8(error.what());
    } catch (...) {
        if (errorOut)
            *errorOut = QStringLiteral("Nieznany błąd rdzenia Rust");
    }
    return false;
}

} // namespace audioticon::ui
